from lib import *
SV = """const int mx = 1000;
bitset<mx> is_prime;
vector<int> primes;
void sieve(int n)
{
    for (int i = 3; i <= n; i += 2) is_prime[i] = 1;
    for (int i = 3; (i * i) <= n; i += 2)
        if (is_prime[i])
            for (int j = i * i; j <= n; j += (i + i)) is_prime[j] = 0;
    is_prime[1] = 0;
    is_prime[2] = 1;
    primes.push_back(2);
    for (int i = 3; i <= n; i += 2)
        if (is_prime[i]) primes.push_back(i);
}"""
N0 = "০১ Harmonic Series ও Divisors"
P("nt", N0, "nt-prime-check", "Prime Check (Trial Division)", "একটা সংখ্যা prime কিনা দেখতে 2 থেকে √n পর্যন্ত ভাগ করে দেখা হয়। কোনোটায় ভাগ গেলে সেটা prime না।", "for (ll i = 2; i * i <= n; i++)\n  if (n % i == 0) not prime;", "O(√n)",
  E("29 prime কিনা", "long long n;\ncin >> n;\nbool prime = n >= 2;\nfor (long long i = 2; i * i <= n; i++)\n    if (n % i == 0) { prime = false; break; }\ncout << (prime ? \"YaaY ! Prime Number\" : \"OPPS ! Not a Prime Number\");", "29 কে 2, 3, 4, 5 দিয়ে ভাগ করলে কোনোটায় নিঃশেষে ভাগ যায় না (6×6 > 29, তাই থামে)। তাই prime।", "29"),
  E("91 prime কিনা", "long long n;\ncin >> n;\nbool prime = n >= 2;\nfor (long long i = 2; i * i <= n; i++)\n    if (n % i == 0) { prime = false; break; }\ncout << (prime ? \"YaaY ! Prime Number\" : \"OPPS ! Not a Prime Number\");", "91 = 7 × 13। i = 7 এ ভাগ যায় (7×7 = 49 ≤ 91), তাই prime না।", "91"))
P("nt", N0, "nt-divisors", "একটা সংখ্যার সব Divisor", "i দিয়ে n ভাগ গেলে i এবং n / i দুইটাই divisor। তাই √n পর্যন্ত গেলেই সব divisor পাওয়া যায়।", "for (ll i = 1; i * i <= n; i++)\n  if (n % i == 0) { i, n / i }", "O(√n)",
  E("36 এর divisor", "long long n;\ncin >> n;\nset<long long> s;\nfor (long long i = 1; i * i <= n; i++)\n    if (n % i == 0) s.insert({i, n / i});\nfor (auto u : s) cout << u << ' ';", "1×36, 2×18, 3×12, 4×9, 6×6 জোড়া থেকে divisor পাওয়া গেলো। 6 দুইবার আসে কিন্তু set-এ একবারই থাকে।", "36"))
P("nt", N0, "nt-cnt-sum-divisors", "Divisor এর সংখ্যা ও যোগফল", "এক লুপেই divisor-এর সংখ্যা (cnt) ও যোগফল (sum) বের করা যায়।", "cnt++; sum += i;\nif (i != n / i) { cnt++; sum += n / i; }", "O(√n)",
  E("12 এর cnt ও sum", "long long n, cnt = 0, sum = 0;\ncin >> n;\nfor (long long i = 1; i * i <= n; i++) {\n    if (n % i == 0) {\n        cnt++; sum += i;\n        if (i != n / i) { cnt++; sum += n / i; }\n    }\n}\ncout << cnt << \" \" << sum;", "12 এর divisor 1, 2, 3, 4, 6, 12 — ৬টা, যোগফল 28।", "12"),
  E("perfect square 36", "long long n, cnt = 0, sum = 0;\ncin >> n;\nfor (long long i = 1; i * i <= n; i++) {\n    if (n % i == 0) {\n        cnt++; sum += i;\n        if (i != n / i) { cnt++; sum += n / i; }\n    }\n}\ncout << cnt << \" \" << sum;", "36 এ i = 6 হলে n / i ও 6 সমান, তাই i != n / i চেক না থাকলে 6 দুইবার গোনা হতো। cnt = 9, sum = 91।", "36"))
P("nt", N0, "nt-1toN-naive", "1 থেকে N সব সংখ্যার Divisor (Naive)", "প্রতিটা সংখ্যার জন্য আলাদা করে √ পর্যন্ত লুপ চালানো হয়।", "for i in 1..n: for j in 1..√i", "O(n √n)",
  E("n = 10", "int n;\ncin >> n;\nvector<vector<int>> d(n + 1);\nfor (int i = 1; i <= n; i++) {\n    for (int j = 1; j * j <= i; j++)\n        if (i % j == 0) {\n            d[i].push_back(j);\n            if (i / j != j) d[i].push_back(i / j);\n        }\n    sort(d[i].begin(), d[i].end());\n}\nfor (int i = 1; i <= n; i++) {\n    cout << i << \" : \";\n    for (auto u : d[i]) cout << u << ' ';\n    cout << endl;\n}", "প্রতিটা সংখ্যার divisor আলাদা vector-এ জমা হয়েছে। যেমন 6 : 1 2 3 6।", "10"))
P("nt", N0, "nt-1toN-harmonic", "1 থেকে N সব Divisor (Harmonic Series)", "i এর সব গুণিতক j-তে i একটা divisor। তাই i এর গুণিতকে গিয়ে push করলেই হয়। মোট ধাপ n/1 + n/2 + ... + n/n ≈ n ln n (Harmonic Series)।", "for (int i = 1; i <= n; i++)\n  for (int j = i; j <= n; j += i)\n    d[j].push_back(i);", "O(n log n)",
  E("n = 10", "int n;\ncin >> n;\nvector<vector<int>> d(n + 1);\nfor (int i = 1; i <= n; i++)\n    for (int j = i; j <= n; j += i)\n        d[j].push_back(i);\nfor (int i = 1; i <= n; i++) {\n    cout << i << \" : \";\n    for (auto u : d[i]) cout << u << ' ';\n    cout << endl;\n}", "i = 2 এ j = 2, 4, 6, 8, 10 তে 2 ঢুকেছে। i আসে ছোট থেকে বড় ক্রমে, তাই divisor আপনা-আপনি সাজানো। Naive এর সাথে একই ফল, কিন্তু অনেক দ্রুত।", "10"))

N1 = "০২ Sieve of Eratosthenes"
P("nt", N1, "nt-sieve-basic", "Basic Sieve", "1 থেকে n পর্যন্ত সব prime একসাথে বের করা। প্রথমে সবাইকে prime ধরে, প্রতিটা সংখ্যার গুণিতক কেটে দেওয়া হয়।", "vector<bool> is_prime(mx, 1);\nfor j = i + i; j <= n; j += i → 0", "O(n log n)",
  E("n = 20", "const int mx = 1000;\nvector<bool> is_prime(mx, 1);\nvector<int> prime;\nint n = 20;\nis_prime[1] = 0;\nfor (int i = 2; i <= n; i++)\n    for (int j = i + i; j <= n; j += i)\n        is_prime[j] = 0;\nfor (int i = 1; i <= n; i++)\n    if (is_prime[i]) prime.push_back(i);\nfor (auto u : prime) cout << u << ' ';", "2 এর গুণিতক 4, 6, 8... কাটা, 3 এর গুণিতক 6, 9, 12... কাটা — এভাবে যা বাকি থাকে সেগুলো prime।"))
P("nt", N1, "nt-sieve-bitset", "Bitset Sieve (দ্রুত ও কম মেমোরি)", "শুধু বিজোড় সংখ্যা নিয়ে কাজ করা হয় (2 আলাদা prime) এবং কাটা শুরু হয় i * i থেকে। bitset এ মেমোরি খুব কম লাগে, তাই 1e8 পর্যন্তও চলে।", "bitset<mx> is_prime;\nfor (j = i * i; j <= n; j += i + i)", "O(n log log n)",
  E("n = 50", "const int mx = 1000;\nbitset<mx> is_prime;\nvector<int> primes;\nint n = 50;\nfor (int i = 3; i <= n; i += 2) is_prime[i] = 1;\nfor (int i = 3; (i * i) <= n; i += 2)\n    if (is_prime[i])\n        for (int j = i * i; j <= n; j += (i + i)) is_prime[j] = 0;\nis_prime[1] = 0;\nis_prime[2] = 1;\nprimes.push_back(2);\nfor (int i = 3; i <= n; i += 2)\n    if (is_prime[i]) primes.push_back(i);\nfor (auto u : primes) cout << u << ' ';\ncout << endl << primes.size();", "50 পর্যন্ত মোট ১৫টা prime আছে। (i + i) ধাপে চলায় শুধু বিজোড় গুণিতকই কাটা পড়ে।"))
P("nt", N1, "nt-sieve-query", "Sieve দিয়ে অনেক query", "একবার sieve চালিয়ে রাখলে যেকোনো সংখ্যা prime কিনা O(1) এ জানা যায়।", "is_prime[x]", "O(1) প্রতি query",
  E("৩টা query", "int q, x;\ncin >> q;\nwhile (q--) {\n    cin >> x;\n    cout << (is_prime[x] ? \"Prime\" : \"Not Prime\") << endl;\n}", "sieve(1000) একবার চালিয়ে তারপর প্রতি query তে শুধু is_prime[x] দেখা হয়েছে।", "3\n7\n100\n997", pre=SV + "\nstruct Init { Init() { sieve(999); } } init;"))

N2 = "০৩ Prime Factorization"
P("nt", N2, "nt-pf-without-sieve", "Prime Factorization (Sieve ছাড়া)", "প্রথমে 2 দিয়ে যতবার সম্ভব ভাগ, তারপর বিজোড় i দিয়ে √n পর্যন্ত ভাগ। শেষে n > 2 থাকলে সেটাই একটা prime factor।", "while (n % i == 0) { pf.push_back(i); n /= i; }", "O(√n)",
  E("360", "int n;\ncin >> n;\nvector<int> pf;\nwhile (n % 2 == 0) { pf.push_back(2); n /= 2; }\nfor (int i = 3; i <= sqrt(n); i += 2)\n    while (n % i == 0) { pf.push_back(i); n /= i; }\nif (n > 2) pf.push_back(n);\nfor (auto u : pf) cout << u << ' ';", "360 = 2×2×2×3×3×5। প্রথমে তিনবার 2, তারপর দুইবার 3, শেষে 5 বাকি থাকে।", "360"),
  E("prime 97", "int n;\ncin >> n;\nvector<int> pf;\nwhile (n % 2 == 0) { pf.push_back(2); n /= 2; }\nfor (int i = 3; i <= sqrt(n); i += 2)\n    while (n % i == 0) { pf.push_back(i); n /= i; }\nif (n > 2) pf.push_back(n);\nfor (auto u : pf) cout << u << ' ';", "97 কোনো i দিয়ে ভাগ যায়নি, তাই শেষে n > 2 হিসেবে 97 নিজেই factor।", "97"))
P("nt", N2, "nt-pf-with-sieve", "Prime Factorization (Sieve দিয়ে)", "শুধু prime দিয়ে ভাগ করা হয়, তাই দ্রুত। p * p > n হলে থামা হয়, আর শেষে n > 1 থাকলে সেটাও prime factor।", "for (auto p : primes) {\n  if (1LL * p * p > n) break;\n  while (n % p == 0) ...", "O(√n / ln √n)",
  E("1001", "int n;\ncin >> n;\nsieve(999);\nvector<int> pf;\nfor (auto p : primes) {\n    if (1LL * p * p > n) break;\n    while (n % p == 0) { pf.push_back(p); n /= p; }\n}\nif (n > 1) pf.push_back(n);\nfor (auto u : pf) cout << u << ' ';", "1001 = 7 × 11 × 13। prime দিয়ে ভাগ করতে করতে 7, 11, 13 পাওয়া গেলো।", "1001", pre=SV))
P("nt", N2, "nt-pf-1toN", "1 থেকে N সব সংখ্যার Prime Factor", "প্রতিটা prime p এর সব গুণিতকে p কে factor হিসেবে জমা করা হয়। Harmonic series এর কারণে দ্রুত।", "for (auto p : primes)\n  for (int i = p; i <= n; i += p)\n    pf[i].push_back(p);", "O(n log log n)",
  E("n = 12", "int n = 12;\nsieve(100);\nvector<vector<int>> pf(n + 1);\nfor (auto p : primes) {\n    if (p > n) break;\n    for (int i = p; i <= n; i += p) pf[i].push_back(p);\n}\nfor (int i = 2; i <= n; i++) {\n    cout << i << \" : \";\n    for (auto u : pf[i]) cout << u << ' ';\n    cout << endl;\n}", "প্রতিটা আলাদা prime একবারই জমা হয়: 6 : 2 3, 10 : 2 5। 4 ও 8 এ শুধু 2 (ঘাত গোনা হয় না), আর 12 : 2 3।", pre=SV))
P("nt", N2, "nt-gcd", "GCD (গ.সা.গু)", "Euclid নিয়ম: gcd(a, b) = gcd(b, a % b)। b = 0 হলে উত্তর a।", "int GCD(int a, int b) {\n  if (b == 0) return a;\n  return GCD(b, a % b);\n}\n__gcd(a, b);", "O(log min(a, b))",
  E("নিজের GCD ও __gcd", "int a = 12, b = 6;\ncout << GCD(a, b) << \" \" << __gcd(a, b) << endl;\ncout << GCD(17, 5) << \" \" << GCD(100, 75);", "12 ও 6 এর GCD 6। 17 ও 5 পরস্পর মৌলিক, তাই 1। 100 ও 75 এর GCD 25।", pre="int GCD(int a, int b)\n{\n    if (b == 0) return a;\n    return GCD(b, a % b);\n}"))
P("nt", N2, "nt-lcm", "LCM (ল.সা.গু)", "LCM(a, b) = (a / gcd(a, b)) * b। আগে ভাগ করলে overflow কম হয়।", "(a / __gcd(a, b)) * b", "O(log min(a, b))",
  E("LCM", "long long a, b;\ncin >> a >> b;\ncout << (a / __gcd(a, b)) * b;", "12 ও 18 এর GCD 6, তাই LCM = 12 / 6 × 18 = 36।", "12 18"),
  E("array এর LCM", "int n;\ncin >> n;\nlong long l = 1, x;\nwhile (n--) {\n    cin >> x;\n    l = (l / __gcd(l, x)) * x;\n}\ncout << l;", "একটা একটা করে LCM বের করে এগোনো হলো: LCM(2,3,4) = 12।", "3\n2 3 4"))

N3 = "০৪ NOD — Divisor সংখ্যা"
P("nt", N3, "nt-nod", "NOD (Prime Factorization দিয়ে)", "n = p1^a1 × p2^a2 × ... হলে divisor সংখ্যা = (a1 + 1) × (a2 + 1) × ...। শেষে n > 1 থাকলে সেটা এক ঘাতের prime, তাই ×2।", "ans *= (cnt + 1);", "O(√n / ln √n)",
  E("6345 ও তুলনা", "int n = 6345, cnt = 0;\nsieve(999);\ncout << NOD(n) << endl;\nfor (int i = 1; i <= n; i++)\n    if (n % i == 0) cnt++;\ncout << cnt;", "6345 = 3³ × 5 × 47, তাই (3+1)(1+1)(1+1) = 16। নিচের লুপে 1 থেকে n পর্যন্ত গুনে দেখা গেলো ১৬ই।", pre=SV + "\nint NOD(long long n)\n{\n    int ans = 1;\n    for (auto p : primes) {\n        if (1LL * p * p > n) break;\n        if (n % p == 0) {\n            int cnt = 1;\n            while (n % p == 0) { n /= p; cnt++; }\n            ans *= cnt;\n        }\n    }\n    if (n > 1) ans *= 2;\n    return ans;\n}"),
  E("৩টা সংখ্যা", "int t;\ncin >> t;\nsieve(999);\nwhile (t--) {\n    long long n;\n    cin >> n;\n    cout << NOD(n) << endl;\n}", "36 = 2²×3² → 9। 100 = 2²×5² → 9। 97 prime → 2।", "3\n36\n100\n97", pre=SV + "\nint NOD(long long n)\n{\n    int ans = 1;\n    for (auto p : primes) {\n        if (1LL * p * p > n) break;\n        if (n % p == 0) {\n            int cnt = 1;\n            while (n % p == 0) { n /= p; cnt++; }\n            ans *= cnt;\n        }\n    }\n    if (n > 1) ans *= 2;\n    return ans;\n}"))
N4 = "০৫ GCD using NOD"
P("nt", N4, "nt-common-divisors", "দুই সংখ্যার Common Divisor সংখ্যা", "a ও b এর সব common divisor আসলে gcd(a, b) এর divisor। তাই common divisor সংখ্যা = NOD(gcd(a, b))।", "NOD(__gcd(a, b))", "O(√gcd)",
  E("12 ও 18", "int a, b;\ncin >> a >> b;\nint g = __gcd(a, b), cnt = 0;\nfor (int i = 1; i * i <= g; i++)\n    if (g % i == 0) cnt += (i == g / i) ? 1 : 2;\ncout << \"GCD = \" << g << endl << \"Common divisors = \" << cnt;", "gcd(12, 18) = 6, আর 6 এর divisor 1, 2, 3, 6 — মোট ৪টা। এগুলোই 12 ও 18 দুইটারই divisor।", "12 18"))
N5 = "০৬ SOD — Divisor এর যোগফল"
P("nt", N5, "nt-sod-series", "SOD (Series দিয়ে)", "p^k এর divisor-যোগফল = 1 + p + p² + ... + p^k। সব prime-এর জন্য এই যোগফল গুণ করলে SOD পাওয়া যায়।", "CurrentSum += PowerOfPrime;\nans *= CurrentSum;", "O(√n / ln √n)",
  E("SOD(12)", "sieve(999);\ncout << SOD(12);", "12 = 2² × 3। (1+2+4) × (1+3) = 7 × 4 = 28।", pre=SV + "\nlong long SOD(long long n)\n{\n    long long ans = 1;\n    for (auto p : primes) {\n        if (1LL * p * p > n) break;\n        if (n % p == 0) {\n            long long cur = 1, pw = 1;\n            while (n % p == 0) { pw *= p; cur += pw; n /= p; }\n            ans *= cur;\n        }\n    }\n    if (n > 1) ans *= (n + 1);\n    return ans;\n}"))
P("nt", N5, "nt-sod-formula", "SOD (Formula দিয়ে)", "Geometric series এর সূত্র: 1 + p + ... + p^k = (p^(k+1) - 1) / (p - 1)। লুপে যোগ না করে সরাসরি সূত্র বসানো হয়।", "ans *= (PowerOfPrime - 1) / (p - 1);", "O(√n / ln √n)",
  E("৩টা query", "int t;\ncin >> t;\nsieve(999);\nwhile (t--) {\n    long long n;\n    cin >> n;\n    cout << SODFormula(n) << endl;\n}", "12 → 28। 100 = 2²×5² → 7 × 31 = 217। 7 prime → 1 + 7 = 8।", "3\n12\n100\n7", pre=SV + "\nlong long SODFormula(long long n)\n{\n    long long ans = 1;\n    for (auto p : primes) {\n        if (1LL * p * p > n) break;\n        if (n % p == 0) {\n            long long pw = p;\n            while (n % p == 0) { pw *= p; n /= p; }\n            ans *= ((pw - 1) / (p - 1));\n        }\n    }\n    if (n > 1) ans *= (n + 1);\n    return ans;\n}"))
N6 = "০৭ SNOD — Divisor সংখ্যার যোগফল"
P("nt", N6, "nt-snod-normal", "SNOD (Normal, O(n))", "SNOD = 1 থেকে n পর্যন্ত সব সংখ্যার divisor সংখ্যার যোগফল। i, n পর্যন্ত ⌊n / i⌋ টা সংখ্যার divisor, তাই SNOD = Σ ⌊n / i⌋।", "sum += n / i;", "O(n)",
  E("n = 10", "long long n = 10, sum = 0;\nfor (int i = 1; i <= n; i++) sum += n / i;\ncout << sum;", "10/1 + 10/2 + ... + 10/10 = 10+5+3+2+2+1+1+1+1+1 = 27। যাচাই: 1..10 এর divisor সংখ্যা 1,2,2,3,2,4,2,4,3,4 — যোগফলও 27।"))
P("nt", N6, "nt-snod-efficient", "SNOD (Efficient, O(√n))", "⌊n / i⌋ এর মান √n এর পর পুনরাবৃত্তি হয়। তাই √n পর্যন্ত গিয়ে 2 দিয়ে গুণ ও u যোগ করলেই হয়।", "ans += (n / i) - i;\nans *= 2;\nans += u;", "O(√n)",
  E("দুই পদ্ধতির তুলনা", "long long n = 120;\nlong long a = 0, u = sqrt(n), b = 0;\nfor (int i = 1; i <= n; i++) a += n / i;\nfor (int i = 1; i <= u; i++) b += (n / i) - i;\nb = b * 2 + u;\ncout << a << \" \" << b;", "Normal O(n) ও Efficient O(√n) দুই পদ্ধতিতেই ফল একই — SNOD(120) = 602। কিন্তু দ্বিতীয়টা অনেক কম ধাপে।"))
N7 = "০৮ Modular Arithmetic"
P("nt", N7, "nt-mod-basic", "Modular যোগ, বিয়োগ, গুণ", "উত্তর অনেক বড় হলে সাধারণত 1e9+7 দিয়ে mod করে বলা হয়। (a+b)%m, (a*b)%m এভাবে প্রতি ধাপে mod করা যায়। বিয়োগে ঋণাত্মক এড়াতে + m করতে হয়।", "(a + b) % m\n(a * b) % m\n(a - b + m) % m", "O(1)",
  E("বড় সংখ্যা", "const int mod = 1000000007;\nlong long a = 1000000000, b = 1000000000;\ncout << (a + b) % mod << endl;\ncout << (a * b) % mod << endl;\ncout << (3 - 5 + mod) % mod;", "a + b = 2×10⁹, mod করলে 999999993। গুণ 10¹⁸, এটাকে mod করলে 49 (long long এ ধরা হয়েছে, int এ হলে overflow হতো)। 3 - 5 = -2, তাই mod যোগ করে ধনাত্মক বানানো: 1000000005।"))
P("nt", N7, "nt-factorial-mod", "Factorial mod", "n! খুব তাড়াতাড়ি বিশাল হয়, তাই প্রতি ধাপেই mod করে রাখতে হয়।", "ans = (ans * i) % mod;", "O(n)",
  E("n! % mod", "const long long mod = 1000000007;\nlong long n, ans = 1;\ncin >> n;\nfor (int i = 1; i <= n; i++) {\n    ans *= i;\n    ans %= mod;\n}\ncout << ans;", "5! = 120। 20! এর মান 64-bit এর কাছাকাছি, তাই প্রতি ধাপে mod করলে নিরাপদ উত্তর পাওয়া যায়।", "5"),
  E("n = 20", "const long long mod = 1000000007;\nlong long n, ans = 1;\ncin >> n;\nfor (int i = 1; i <= n; i++) {\n    ans *= i;\n    ans %= mod;\n}\ncout << ans;", "20! = 2432902008176640000, এটাকে 1e9+7 দিয়ে mod করলে যা আসে তা নিচে দেখা যাচ্ছে।", "20"))
P("nt", N7, "nt-binary-exponentiation", "Binary Exponentiation (দ্রুত power)", "b^p কে p বার গুণ না করে p এর বিট ধরে O(log p) তে বের করা হয়। p এর শেষ বিট 1 হলে ans এ গুণ হয়, প্রতি ধাপে b বর্গ হয় ও p অর্ধেক হয়।", "while (p) {\n  if (p & 1) ans = ans * b % mod;\n  b = b * b % mod;\n  p >>= 1;\n}", "O(log p)",
  E("2^10", "int base, power;\ncin >> base >> power;\ncout << BinaryExponentiation(base, power);", "2^10 = 1024। 10 = 1010 (বাইনারি), তাই b = 2⁸ ও 2² গুণ হয়: 256 × 4 = 1024।", "2 10", pre="#define mod 1000000007\nint BinaryExponentiation(int b, int p)\n{\n    int ans = 1;\n    while (p) {\n        if (p & 1) ans = (ans * 1LL * b) % mod;\n        b = (b * 1LL * b) % mod;\n        p >>= 1;\n    }\n    return ans;\n}"),
  E("3^1000000", "int base, power;\ncin >> base >> power;\ncout << BinaryExponentiation(base, power);", "power 10⁶ হলেও মাত্র প্রায় ২০ ধাপে (log₂ 10⁶ ≈ 20) উত্তর বের হয়।", "3 1000000", pre="#define mod 1000000007\nint BinaryExponentiation(int b, int p)\n{\n    int ans = 1;\n    while (p) {\n        if (p & 1) ans = (ans * 1LL * b) % mod;\n        b = (b * 1LL * b) % mod;\n        p >>= 1;\n    }\n    return ans;\n}"))
N8 = "০৯ Modular Inverse ও Division"
BE = "#define mod 1000000007\nint BinaryExponentiation(int b, int p)\n{\n    int ans = 1;\n    while (p) {\n        if (p & 1) ans = (ans * 1LL * b) % mod;\n        b = (b * 1LL * b) % mod;\n        p >>= 1;\n    }\n    return ans;\n}"
P("nt", N8, "nt-mod-inverse", "Modular Inverse (Fermat)", "mod ভাগ করা যায় না। তাই a / b % m = a × inverse(b) % m। m prime হলে Fermat এর সূত্র: inverse(b) = b^(m-2) % m।", "BinaryExponentiation(b, mod - 2)", "O(log mod)",
  E("3 এর inverse", "int b = 3;\nint inv = BinaryExponentiation(b, mod - 2);\ncout << inv << endl;\ncout << (1LL * b * inv) % mod;", "3 × 333333336 = 1000000008 ≡ 1 (mod 1e9+7)। তাই 333333336 ই 3 এর inverse।", pre=BE),
  E("modular division", "int a = 6, b = 3;\nint ans = (a * 1LL * BinaryExponentiation(b, mod - 2)) % mod;\ncout << ans;", "6 / 3 কে mod এ করতে 6 × inverse(3) করা হয়েছে। ফল 2, যেটা সাধারণ ভাগের সাথে মেলে।", pre=BE))
P("nt", N8, "nt-ncr", "nCr mod (Factorial + Inverse)", "nCr = n! / ((n-r)! × r!)। ভাগের জায়গায় denominator এর inverse দিয়ে গুণ করা হয়। factorial আগেই বের করে রাখলে প্রতি query O(log mod)।", "fact[n] * inverse(fact[n-r] * fact[r])", "O(log mod) প্রতি query",
  E("৩টা query", "const int mx = 1000;\nint fact[mx];\nfact[0] = 1;\nfor (int i = 1; i < mx; i++) fact[i] = (fact[i - 1] * 1LL * i) % mod;\nint q;\ncin >> q;\nwhile (q--) {\n    int n, k;\n    cin >> n >> k;\n    int b = (fact[n - k] * 1LL * fact[k]) % mod;\n    int inv = BinaryExponentiation(b, mod - 2);\n    cout << (fact[n] * 1LL * inv) % mod << endl;\n}", "C(5,2) = 10, C(10,3) = 120, C(6,6) = 1। এখানে fact[] একবার বানানো, তারপর প্রতিটা query তে শুধু inverse বের করা হয়েছে।", "3\n5 2\n10 3\n6 6", pre=BE))
N9 = "১০ Euler Totient (Phi) Function"
P("nt", N9, "nt-euler-phi", "Euler Phi φ(n)", "φ(n) = 1 থেকে n এর মধ্যে কয়টা সংখ্যা n এর সাথে পরস্পর মৌলিক (gcd = 1)। সূত্র: φ(n) = n × (1 - 1/p1) × (1 - 1/p2) × ...", "ans = ans / p * (p - 1);", "O(√n)",
  E("36, 13, 100", "int t;\ncin >> t;\nwhile (t--) {\n    int n;\n    cin >> n;\n    cout << EulerPhi(n) << endl;\n}", "36 = 2²×3² → 36 × ½ × ⅔ = 12। 13 prime → 12। 100 = 2²×5² → 100 × ½ × ⅘ = 40।", "3\n36\n13\n100", pre="int EulerPhi(int n)\n{\n    int ans = n;\n    for (int p = 2; 1LL * p * p <= n; p++) {\n        if (n % p == 0) {\n            ans = ans / p * (p - 1);\n            while (n % p == 0) n /= p;\n        }\n    }\n    if (n > 1) ans = ans / n * (n - 1);\n    return ans;\n}"),
  E("গুনে যাচাই", "int n = 12, cnt = 0;\nfor (int i = 1; i <= n; i++)\n    if (__gcd(i, n) == 1) { cout << i << ' '; cnt++; }\ncout << endl << cnt;", "12 এর সাথে পরস্পর মৌলিক সংখ্যা 1, 5, 7, 11 — ৪টা। সূত্রেও φ(12) = 12 × ½ × ⅔ = 4।"))
P("nt", N9, "nt-phi-1toN", "1 থেকে N সব φ (Sieve style)", "ঠিক Harmonic series এর মতো: প্রতিটা prime p এর গুণিতক i এর জন্য phi[i] -= phi[i] / p।", "for p prime: for i = p; i <= n; i += p\n  phi[i] -= phi[i] / p;", "O(n log log n)",
  E("n = 12", "int n = 12;\nvector<int> phi(n + 1);\nfor (int i = 0; i <= n; i++) phi[i] = i;\nfor (int p = 2; p <= n; p++)\n    if (phi[p] == p)\n        for (int i = p; i <= n; i += p) phi[i] -= phi[i] / p;\nfor (int i = 1; i <= n; i++) cout << \"phi(\" << i << \") = \" << phi[i] << endl;", "phi[p] == p থাকলে p এখনো কাটা পড়েনি, মানে p prime। 1 থেকে 12 সব φ একবারেই বের হয়েছে।"))
N10 = "১১ Euler Phi Extension Theorem"
P("nt", N10, "nt-phi-extension", "Σ φ(d) = n (Extension Theorem)", "n এর সব divisor d এর φ(d) যোগ করলে ঠিক n পাওয়া যায়।", "Σ φ(d) for d | n  =  n", "O(n)",
  E("n = 12", "int n = 12, sum = 0;\nfor (int d = 1; d <= n; d++) {\n    if (n % d) continue;\n    int c = 0;\n    for (int i = 1; i <= d; i++) if (__gcd(i, d) == 1) c++;\n    cout << \"phi(\" << d << \") = \" << c << endl;\n    sum += c;\n}\ncout << \"Sum = \" << sum;", "12 এর divisor 1, 2, 3, 4, 6, 12। তাদের φ: 1, 1, 2, 2, 2, 4 — যোগফল 12, ঠিক n এর সমান।"))
